function numToWordsRu(num) {
  const units = ['', 'один', 'два', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
  const unitsFem = ['', 'одна', 'две', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
  const teens = ['десять', 'одиннадцать', 'двенадцать', 'тринадцать', 'четырнадцать', 'пятнадцать', 'шестнадцать', 'семнадцать', 'восемнадцать', 'девятнадцать'];
  const tens = ['', '', 'двадцать', 'тридцать', 'сорок', 'пятьдесят', 'шестьдесят', 'семьдесят', 'восемьдесят', 'девяно0сто'];
  const hundreds = ['', 'сто', 'двести', 'триста', 'четыреста', 'пятьсот', 'шестьсот', 'семьсот', 'восемьсот', 'девятьсот'];

  function morph(n, f1, f2, f5) {
    n = Math.abs(n) % 100;
    const n1 = n % 10;
    if (n > 10 && n < 20) return f5;
    if (n1 > 1 && n1 < 5) return f2;
    if (n1 === 1) return f1;
    return f5;
  }

  function tripletToWords(n, isFemale) {
    let str = '';
    const h = Math.floor(n / 100);
    const t = Math.floor((n % 100) / 10);
    const u = n % 10;

    if (h > 0) str += hundreds[h] + ' ';
    if (t === 1) {
      str += teens[u] + ' ';
    } else {
      if (t > 1) str += tens[t] + ' ';
      if (u > 0) str += (isFemale ? unitsFem[u] : units[u]) + ' ';
    }
    return str.trim();
  }

  const rubles = Math.floor(num);
  const kopecks = Math.round((num - rubles) * 100);
  if (rubles === 0) return 'ноль рублей 00 копеек';

  const billions = Math.floor(rubles / 1000000000);
  const millions = Math.floor((rubles % 1000000000) / 1000000);
  const thousands = Math.floor((rubles % 1000000) / 1000);
  const remainder = rubles % 1000;

  let result = '';
  if (billions > 0) result += tripletToWords(billions, false) + ' ' + morph(billions, 'миллиард', 'миллиарда', 'миллиардов') + ' ';
  if (millions > 0) result += tripletToWords(millions, false) + ' ' + morph(millions, 'миллион', 'миллиона', 'миллионов') + ' ';
  if (thousands > 0) result += tripletToWords(thousands, true) + ' ' + morph(thousands, 'тысяча', 'тысячи', 'тысяч') + ' ';
  if (remainder > 0) result += tripletToWords(remainder, false) + ' ';

  result += morph(rubles, 'рубль', 'рубля', 'рублей');
  result = result.trim();
  result = result.charAt(0).toUpperCase() + result.slice(1);

  const kopFormatted = kopecks < 10 ? '0' + kopecks : '' + kopecks;
  return `${result} ${kopFormatted} копеек`;
}

let raw = $('Amo: Получить данные сделки').first().json;
if (raw && typeof raw.data === 'string') {
  try { raw = JSON.parse(raw.data); } catch (e) {}
}

const fields = raw.custom_fields_values || [];

function getFieldValue(id) {
  const f = fields.find(item => item.field_id === id);
  return (f && f.values && f.values[0] && f.values[0].value) || null;
}

const debtAmount = Number(getFieldValue(2714917)) || 0;
const claimantInn = getFieldValue(2714919);
const defendantInn = getFieldValue(2714921);
const directorFio = getFieldValue(2714923);
const defendantCompany = getFieldValue(2714925);
const leadId = raw.id;

const missing = [];
if (!claimantInn) missing.push('ИНН истца');
if (!defendantInn) missing.push('ИНН ответчика');
if (!directorFio) missing.push('ФИО директора ответчика');
if (!defendantCompany) missing.push('Название компании ответчика');
if (!debtAmount || debtAmount <= 0) missing.push('Сумма долга');

if (missing.length > 0) {
  return [{
    json: {
      is_valid: false,
      lead_id: leadId,
      missing_fields: missing.join(', ')
    }
  }];
}

const debtFormatted = debtAmount.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const debtWords = numToWordsRu(debtAmount);

return [{
  json: {
    is_valid: true,
    lead_id: leadId,
    debt_amount: debtAmount,
    debt_formatted: debtFormatted,
    debt_words: debtWords,
    claimant_inn: claimantInn,
    defendant_inn: defendantInn,
    director_fio: directorFio,
    defendant_company: defendantCompany
  }
}];

