const prev = $('Code: Парсинг').first().json;
const llmRaw = $input.first().json;

let fioGenitive = prev.director_fio;
try {
  const content = typeof llmRaw.choices[0].message.content === 'string' 
    ? JSON.parse(llmRaw.choices[0].message.content) 
    : llmRaw.choices[0].message.content;
  if (content.fio_genitive) {
    fioGenitive = content.fio_genitive;
  }
} catch (e) {}

const currentYear = new Date().getFullYear();
const docNumber = 'ИСК-' + prev.lead_id;

const htmlContent = `<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="UTF-8">
  <style>
    @page { size: A4; margin: 18mm 15mm 18mm 30mm; }
    body { font-family: 'Times New Roman', Times, serif; color: #000; font-size: 11.5pt; line-height: 1.3; margin: 0; padding: 0; }
    .court-header { width: 58%; margin-left: auto; margin-bottom: 22px; font-size: 10.5pt; line-height: 1.25; }
    .court-header p { margin: 0 0 6px 0; }
    .title { text-align: center; font-size: 13.5pt; font-weight: bold; text-transform: uppercase; letter-spacing: 0.5px; margin: 18px 0 4px 0; }
    .subtitle { text-align: center; font-size: 11pt; font-weight: bold; margin-bottom: 18px; }
    .paragraph { text-align: justify; text-indent: 1.25cm; margin: 0 0 9px 0; }
    .debt-highlight { text-align: justify; text-indent: 1.25cm; font-weight: bold; margin: 10px 0 10px 0; }
    .legal-grounds { font-weight: bold; margin: 14px 0 10px 0; text-indent: 1.25cm; text-align: left; }
    .proshu { text-align: center; font-size: 11.5pt; font-weight: bold; margin: 14px 0 8px 0; letter-spacing: 0.5px; }
    .petitum-item { text-align: justify; text-indent: 1.25cm; margin: 0 0 6px 0; }
    .attachments { margin-top: 16px; font-size: 10pt; line-height: 1.22; }
    .attachments-title { font-weight: bold; margin-bottom: 4px; }
    .attachments ol { margin: 0; padding-left: 22px; }
    .attachments li { margin-bottom: 3px; }
    .signatures { margin-top: 26px; width: 100%; border-collapse: collapse; }
    .signatures td { vertical-align: bottom; font-size: 11pt; }
    .sign-col { text-align: right; white-space: nowrap; }
    .line { border-bottom: 1px solid #000; width: 170px; display: inline-block; margin-right: 6px; }
  </style>
</head>
<body>
  <div class="court-header">
    <p><b>В Арбитражный суд города Москвы</b><br>115225, г. Москва, ул. Большая Тульская, д. 17</p>
    <p><b>Истец:</b> ООО «Правовой Стандарт»<br>ИНН: ${prev.claimant_inn}<br>Адрес: 125009, г. Москва, Тверская ул., д. 1</p>
    <p><b>Ответчик:</b> ${prev.defendant_company}<br>ИНН: ${prev.defendant_inn}<br>в лице Генерального директора<br><b>${fioGenitive}</b></p>
    <p><b>Цена иска:</b> ${prev.debt_formatted} руб.<br><b>Госпошлина:</b> в соответствии со ст. 333.21 НК РФ</p>
  </div>
  <div class="title">ИСКОВОЕ ЗАЯВЛЕНИЕ</div>
  <div class="subtitle">о взыскании задолженности по договору оказания услуг</div>
  <div class="paragraph">Между ООО «Правовой Стандарт» (Истец) и ${prev.defendant_company} (Ответчик) был заключен договор на оказание юридических и консультационных услуг. Истец исполнил принятые на себя договорные обязательства в полном объеме и надлежащим образом (ст. 779 ГК РФ), что подтверждается подписанными сторонами первичными документами и актами сдачи-приемки оказанных услуг.</div>
  <div class="paragraph">В соответствии со ст. 309, 310, 781 ГК РФ обязательства должны исполняться надлежащим образом, односторонний отказ от исполнения обязательств не допускается. Однако Ответчик нарушил согласованные сроки оплаты и до настоящего момента уклоняется от перечисления денежных средств.</div>
  <div class="debt-highlight">Сумма непогашенной задолженности Ответчика перед Истцом составляет ${prev.debt_formatted} (${prev.debt_words}) руб.</div>
  <div class="paragraph">В порядке ч. 5 ст. 4 АПК РФ Истцом в адрес руководства Ответчика (${fioGenitive}) была направлена досудебная претензия с требованием о добровольном погашении долга. Требование оставлено без финансового удовлетворения.</div>
  <div class="legal-grounds">На основании изложенного, руководствуясь ст. 309, 310, 779, 781 ГК РФ, ст. 4, 125, 126 АПК РФ,</div>
  <div class="proshu">ПРОШУ СУД:</div>
  <div class="petitum-item">1. Взыскать с ${prev.defendant_company} (ИНН ${prev.defendant_inn}) в пользу ООО «Правовой Стандарт» задолженность в размере <b>${prev.debt_formatted} руб. (${prev.debt_words})</b>.</div>
  <div class="petitum-item">2. Взыскать с Ответчика в пользу Истца расходы по уплате государственной пошлины.</div>
  <div class="attachments">
    <div class="attachments-title">Приложения:</div>
    <ol>
      <li>Копия договора об оказании услуг и первичных документов.</li>
      <li>Копия досудебной претензии и документов, подтверждающих ее отправку.</li>
      <li>Расчет суммы исковых требований.</li>
      <li>Документ, подтверждающий уплату государственной пошлины.</li>
      <li>Копия доверенности представителя Истца.</li>
    </ol>
  </div>
  <table class="signatures">
    <tr>
      <td style="width: 40%;">«___» ____________ ${currentYear} г.</td>
      <td class="sign-col" style="width: 60%;">Представитель по доверенности:<br><span class="line"></span> / Черняев&nbsp;И.&nbsp;Н.</td>
    </tr>
  </table>
</body>
</html>`;

return [{
  json: {
    ...prev,
    fio_genitive: fioGenitive,
    doc_number: docNumber,
    filename: `Claim_${prev.lead_id}.pdf`,
    html_content: htmlContent
  }
}];

